131	class OptimizeRecoveryTest : public ::testing::Test {
132	 protected:
133	  void SetUp() override {
134	    zvec::test_util::RemoveTestPath("./optimize_recovery_test_db");
135	    ASSERT_NO_THROW(optimizer_bin_ = LocateOptimizeGenerator());
136	  }
137	
138	  void TearDown() override {
139	    zvec::test_util::RemoveTestPath("./optimize_recovery_test_db");
140	  }
141	};
142	
143	
144	TEST_F(OptimizeRecoveryTest, CrashDuringOptimize) {
145	  {  // Create a collection and insert some documents
146	    auto schema = CreateTestSchema(collection_name_);
147	    auto result = Collection::CreateAndOpen(dir_path_, *schema, options_);
148	    ASSERT_TRUE(result.has_value());
149	    auto collection = result.value();
150	
151	    for (int batch = 0; batch < num_batches; batch++) {
152	      std::vector<Doc> docs;
153	      for (int i = 0; i < batch_size; i++) {
154	        docs.push_back(CreateTestDoc(batch * batch_size + i, 0));
155	      }
156	      auto write_result = collection->Insert(docs);
157	      ASSERT_TRUE(write_result);
158	      for (auto &s : write_result.value()) {
159	        ASSERT_TRUE(s.ok());
160	      }
161	    }
162	
163	    ASSERT_EQ(collection->Stats()->doc_count, num_batches * batch_size);
164	    collection.reset();
165	  }
166	
167	  RunOptimizerAndCrash(dir_path_, 4);
168	
169	  {  // Open the collection and verify data integrity
170	    auto result = Collection::Open(dir_path_, options_);
171	    ASSERT_TRUE(result.has_value())
172	        << "Failed to reopen collection after crash. "
173	           "Recovery mechanism may be broken.";
174	    auto collection = result.value();
175	    uint64_t doc_count{collection->Stats().value().doc_count};
176	    ASSERT_EQ(doc_count, num_batches * batch_size);
177	    for (uint64_t doc_id = 0; doc_id < doc_count; doc_id++) {
178	      Doc expected_doc = CreateTestDoc(doc_id, 0);
179	      std::vector<std::string> pks{};
180	      pks.emplace_back(expected_doc.pk());
181	      if (auto res = collection->Fetch(pks); res) {
182	        auto map = res.value();
183	        if (map.find(expected_doc.pk()) == map.end()) {
184	          FAIL() << "Returned map does not contain doc[" << expected_doc.pk()
185	                 << "]";
186	        }
187	        const auto actual_doc = map.at(expected_doc.pk());
188	        ASSERT_EQ(*actual_doc, expected_doc)
189	            << "Data mismatch for doc[" << expected_doc.pk() << "]";
190	      } else {
191	        FAIL() << "Failed to fetch doc[" << expected_doc.pk() << "]";
192	      }
193	    }
194	
195	    SearchQuery query;
196	    query.topk_ = 10;
197	    std::vector<float> feature(128, 0.0);
198	    query.target_.set_vector(std::string((const char *)feature.data(),
199	                                         feature.size() * sizeof(float)));
200	    query.target_.field_name_ = "dense_fp32_field";
201	    auto query_result = collection->Query(query);
202	    ASSERT_TRUE(query_result);
203	    auto doc_list = query_result.value();
204	    ASSERT_EQ(doc_list.size(), 10);
205	    ASSERT_EQ(doc_list[0]->pk(), "pk_0");
206	
207	    // Insert some more documents
208	    for (int batch = num_batches; batch < num_batches + 500; batch++) {
209	      std::vector<Doc> docs;
210	      for (int i = 0; i < batch_size; i++) {
211	        docs.push_back(CreateTestDoc(batch * batch_size + i, 0));
212	      }
213	      auto write_result = collection->Insert(docs);
214	      ASSERT_TRUE(write_result);
215	      for (auto &s : write_result.value()) {
216	        ASSERT_TRUE(s.ok());
217	      }
218	    }
219	
220	    collection.reset();
221	  }
222	
223	  RunOptimizer(dir_path_);
224	
225	  // Open the collection and verify data integrity
226	  auto result = Collection::Open(dir_path_, options_);
227	  ASSERT_TRUE(result.has_value()) << "Failed to reopen collection after crash. "
228	                                     "Recovery mechanism may be broken.";
229	  auto collection = result.value();
230	  uint64_t doc_count{collection->Stats().value().doc_count};
231	  ASSERT_EQ(doc_count, (num_batches + 500) * batch_size);
232	  for (uint64_t doc_id = 0; doc_id < doc_count; doc_id++) {
233	    Doc expected_doc = CreateTestDoc(doc_id, 0);
234	    std::vector<std::string> pks{};
235	    pks.emplace_back(expected_doc.pk());
236	    if (auto res = collection->Fetch(pks); res) {
237	      auto map = res.value();
238	      if (map.find(expected_doc.pk()) == map.end()) {
239	        FAIL() << "Returned map does not contain doc[" << expected_doc.pk()
240	               << "]";
241	      }
242	      const auto actual_doc = map.at(expected_doc.pk());
243	      ASSERT_EQ(*actual_doc, expected_doc)
244	          << "Data mismatch for doc[" << expected_doc.pk() << "]";
245	    } else {
246	      FAIL() << "Failed to fetch doc[" << expected_doc.pk() << "]";
247	    }
248	  }
249	
250	  SearchQuery query;
251	  query.topk_ = 10;
252	  std::vector<float> feature(128, 0.0);
253	  query.target_.set_vector(std::string((const char *)feature.data(),
254	                                       feature.size() * sizeof(float)));
255	  query.target_.field_name_ = "dense_fp32_field";
256	  auto query_result = collection->Query(query);
257	  ASSERT_TRUE(query_result);
258	  auto doc_list = query_result.value();
259	  ASSERT_EQ(doc_list.size(), 10);
260	  ASSERT_EQ(doc_list[0]->pk(), "pk_0");
261	}
